// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    // Fuzzed params: actor address and an _unlockTime value
    function testFuzz_property(address actor, uint256 _unlockTime) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // give actor some ether
        uint256 amt = 1 ether;
        vm.deal(actor, amt);
        // Warp to a known time to make behavior deterministic
        vm.warp(1000);
        // actor calls Put with fuzzed _unlockTime
        vm.startPrank(actor);
        c.Put{value: amt}(_unlockTime);
        vm.stopPrank();

        // Read stored unlockTime via public mapping getter
        (uint256 storedUnlock, uint256 storedBalance) = (c.Acc(actor).unlockTime, c.Acc(actor).balance);

        // General rule: For any input, after Put the reference implementation sets storedUnlock to be
        // equal to block.timestamp when the provided _unlockTime is <= block.timestamp (i.e., past or now).
        // The mutant that treats _unlockTime as a delay will set storedUnlock = block.timestamp + _unlockTime,
        // which for small _unlockTime (>0) makes storedUnlock > block.timestamp, thus violating equality for some inputs.
        // We assert the property that if the provided _unlockTime is <= current block.timestamp then storedUnlock == block.timestamp.

        if (_unlockTime <= block.timestamp) {
            assertTrue(storedUnlock == block.timestamp);
        } else {
            // when _unlockTime > now the reference sets storedUnlock == _unlockTime and that is >= block.timestamp
            assertTrue(storedUnlock >= block.timestamp);
        }
    }
}

