pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor supplies value and _unlockTime
    function testFuzz_property(address actor, uint256 value, uint256 _unlockTime) public {
        // keep actor non-zero and value small enough to avoid trivial extremes
        vm.assume(actor != address(0));
        // bound value to a reasonable range so we can fund the actor
        value = bound(value, 0, 5 ether);
        // fund actor so they can call payable Put
        vm.deal(actor, value);

        // capture block.timestamp for the expected rule
        uint256 t0 = block.timestamp;

        // perform the call from actor sending value
        vm.prank(actor);
        // call Put with fuzzed _unlockTime and fuzzed value
        c.Put{value: value}(_unlockTime);

        // read stored unlockTime via autogenerated getter: Acc returns (unlockTime, balance)
        (uint256 storedUnlock, ) = c.Acc(actor);

        // The universal property (one assert): storedUnlock equals _unlockTime when _unlockTime>t0, otherwise equals t0
        uint256 expected = _unlockTime > t0 ? _unlockTime : t0;
        assertTrue(storedUnlock == expected);
    }
}

