import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz params: actor and _unlockTime
    function testFuzz_property(address actor, uint256 _unlockTime) public {
        // keep actor non-zero to be a valid caller
        vm.assume(actor != address(0));
        // fund actor so Put can be called with some nonzero msg.value if desired
        uint256 sendVal = 1 wei;
        vm.deal(actor, sendVal);

        // record current block time
        uint256 t0 = block.timestamp;

        // call Put as actor with small value
        vm.prank(actor);
        c.Put{value: sendVal}(_unlockTime);

        // read stored unlockTime
        (uint256 storedUnlock,) = getHolder(actor);

        // The universal property: storedUnlock >= t0, and if _unlockTime <= t0 then storedUnlock == t0
        bool prop;
        if (_unlockTime <= t0) {
            prop = (storedUnlock == t0);
        } else {
            prop = (storedUnlock == _unlockTime);
        }

        assertTrue(prop);
    }

    // helper to read public mapping Acc (auto-generated getter has signature Acc(address) returns (uint,uint))
    function getHolder(address who) internal view returns (uint256 unlockTime, uint256 balance) {
        // call the auto-generated getter
        (unlockTime, balance) = c.Acc(who);
    }
