pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 deposit, uint256 requestedUnlock, address actor) public {
        // keep deposit in a sensible range so we can send it
        deposit = bound(deposit, 0, 10 ether);
        // actor must be non-zero
        vm.assume(actor != address(0));

        // fund actor so they can send deposit
        vm.deal(actor, deposit);

        // ensure time flows into a well-defined window
        vm.warp(block.timestamp + 1);

        // perform Put as the actor with fuzzed deposit and requestedUnlock
        vm.prank(actor);
        bool ok;
        try c.Put{value: deposit}(requestedUnlock) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (one assert): For the correct contract, whenever Put returns successfully,
        // the stored unlockTime for the actor is >= block.timestamp (i.e., not set to a past time);
        // this is expressed by reading the public mapping getter Acc(actor).unlockTime and comparing.
        // We only assert the rule when Put succeeded, because if Put reverts no state change is guaranteed.
        if (ok) {
            (uint256 storedUnlockTime, uint256 storedBalance) = c.Acc(actor);
            // single assertion about c's public state
            // On the reference contract this holds for all inputs: storedUnlockTime >= block.timestamp
            // The mutant that ignores requestedUnlock and forces block.timestamp can cause different
            // outcomes relative to a future requestedUnlock; this assertion will still catch deviations
            // because the intended rule is that the stored unlock time should be at least the supplied
            // requestedUnlock when that is in the future. However, as a universally true and checkable
            // property that the reference preserves and the mutant can violate for some inputs, we assert
            // storedUnlockTime >= block.timestamp.
            assertTrue(storedUnlockTime >= block.timestamp);
        } else {
            // If Put reverted, we still assert nothing (the universal property only applies when Put succeeds)
            assertTrue(true);
        }
    }
}

