pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed parameters: actor address and unlockTime requested and deposit amount
    function testFuzz_property(address actor, uint256 requestedUnlock, uint256 deposit) public {
        // keep domains wide but sensible
        vm.assume(actor != address(0));
        // bound deposit to a reasonable Ether-ish amount to avoid overflow in tests
        deposit = bound(deposit, 0, 10 ether);
        // requestedUnlock can be anywhere; keep it within a large window around current time
        // allow requestedUnlock to be in future to expose the mutant
        requestedUnlock = bound(requestedUnlock, 0, block.timestamp + 100 days);

        // fund the actor so they can send ETH
        vm.deal(actor, deposit);

        // perform the call as the actor, sending deposit wei
        vm.prank(actor);
        bool ok;
        try c.Put{value: deposit}(requestedUnlock) {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: when the call succeeded, the stored unlockTime must be >= block.timestamp
        // and also must be >= (requestedUnlock <= block.timestamp ? requestedUnlock : requestedUnlock) in reference
        // We express a general rule that reference satisfies: stored unlockTime >= (requestedUnlock > block.timestamp ? requestedUnlock : block.timestamp)
        // which is equivalent to: stored unlockTime >= requestedUnlock when requestedUnlock > block.timestamp, otherwise >= block.timestamp.
        // Read the stored value via public getter Acc
        (uint storedUnlock, ) = c.Acc(actor);

        // compute the required lower bound per the rule
        uint required = requestedUnlock > block.timestamp ? requestedUnlock : block.timestamp;

        // If the Put call reverted, storedUnlock should be unchanged (default 0) and the inequality may not hold; so only assert when the call succeeded
        if (ok) {
            assertTrue(storedUnlock >= required);
        } else {
            // if call failed, still assert storedUnlock >= 0 to have a single assertTrue in all paths (succeeds on reference)
            assertTrue(storedUnlock >= 0);
        }
    }
}

