pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    // fuzzed params: actor address and a future unlock time and a deposit amount
    function testFuzz_property(address actor, uint256 deposit, uint256 futureOffset) public {
        // Keep domain wide but meaningful:
        // actor must be non-zero and not this contract to simulate external caller
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // deposit at least 1 wei and bounded to avoid overflow in vm.deal
        deposit = bound(deposit, 1, 1 ether);
        // futureOffset should produce a future timestamp reasonably ahead of block.timestamp
        // allow up to 1 week in future to keep wide
        futureOffset = bound(futureOffset, 1, 1 weeks);

        uint256 requested = block.timestamp + futureOffset; // this is > block.timestamp by construction

        // fund and act as the actor to call Put
        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Put{value: deposit}(requested);

        // Exactly one assertion: for the correct contract, when caller requests a strictly future unlock
        // the stored unlockTime must equal the requested future time. The mutant that forces block.timestamp
        // will fail for some such inputs (the fuzzer can discover those).
        (uint256 storedUnlockTime, uint256 storedBalance) = getHolder(actor);
        // storedBalance is touched only to ensure the returned tuple corresponds to Acc[actor]
        // assert the key property
        assertTrue(storedUnlockTime == requested);
    }

    // helper to read the Acc mapping via the autogenerated getter: mapping (address => Holder) public Acc;
    // The compiler generates Acc(address) returns (uint unlockTime, uint balance)
    function getHolder(address a) internal returns (uint256, uint256) {
        return c.Acc(a);
    }
}

