pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public { c = new C(address(this)); caller = new Caller(address(c)); }

    // fuzz _unlockTime and sentValue; the adversarial component is that the caller is a contract
    // which will warp time forward just before calling Put, so we ensure the reference respects
    // that future unlockTime (it will set stored unlockTime to _unlockTime if in future), while
    // the mutant that forces block.timestamp will set stored unlockTime to the current timestamp
    // at Put execution which can be smaller than the requested future _unlockTime.
    function testFuzz_property(uint256 _unlockTime, uint256 sentValue) public {
        // keep sentValue reasonable and non-zero so Put changes state; keep wide bounds
        sentValue = bound(sentValue, 1 wei, 5 ether);

        // pick an _unlockTime at least slightly in the future of current block.timestamp
        // allow fuzz to choose any uint; but require it be > block.timestamp so the distinguishing
        // case is admissible. If not, we skip (reference and mutant behave same).
        vm.assume(_unlockTime > block.timestamp + 1);

        // fund the caller contract so it can forward the payment
        vm.deal(address(caller), sentValue);

        // Caller will warp to a point after current block.timestamp but before _unlockTime,
        // then call Put with the requested future _unlockTime. For the reference C, since
        // _unlockTime > block.timestamp it should store acc.unlockTime = _unlockTime (>= that future time).
        // For the mutant that forces acc.unlockTime = block.timestamp (the time at Put), the stored
        // unlockTime will be the warped time which is < _unlockTime, causing the property to fail.

        // instruct caller to perform the call; it warps to block.timestamp + 1 and then calls Put
        caller.doPut{value: sentValue}(_unlockTime);

        // single universal assertion: stored unlockTime for caller equals or exceeds the current
        // block.timestamp (i.e., never set to a time in the past). This holds for the reference for
        // all admissible inputs (including future _unlockTime) because the reference sets to
        // max(_unlockTime, block.timestamp) while our caller ensured _unlockTime is in the future,
        // so stored unlockTime >= block.timestamp holds. The mutant can set acc.unlockTime to a
        // smaller value than the supplied future _unlockTime, but still >= block.timestamp at the
        // moment of Put; to detect the mutant we instead assert that stored unlockTime >= _unlockTime,
        // which the reference preserves for future _unlockTime but the mutant violates.

        // Therefore assert the stricter property: stored unlockTime >= _unlockTime. This is true for
        // reference C for all admissible inputs (we required _unlockTime > block.timestamp+1), and
        // the mutant that forces acc.unlockTime = block.timestamp will fail when block.timestamp < _unlockTime.

        uint stored = c.Acc(address(caller));
        // c.Acc(address) is a struct getter returning (unlockTime, balance) tuple; access unlockTime
        // The auto-generated getter signature: function Acc(address) public view returns (uint unlockTime, uint balance);
        (uint unlockTimeStored, ) = c.Acc(address(caller));

        assertTrue(unlockTimeStored >= _unlockTime);
    }
}

// Minimal helper contract that warps time and forwards the call to C
contract Caller {
    address caddr;
    constructor(address _caddr) payable { caddr = _caddr; }

    // receive funds when vm.deal funds this contract
    receive() external payable {}

    // warp forward a bit and then call Put on C, forwarding ETH
    function doPut(uint _unlockTime) external payable {
        // Advance time to simulate a change in block.timestamp before Put executes
        // We cannot call vm.warp here; test uses vm.prank to call this function under test control.
        // Instead, the test's call to Caller was funded and executed in the test context, and
        // the caller simply forwards the call to C.
        C(caddr).Put{value: msg.value}(_unlockTime);
    }
}

