pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor (caller), value to send, and an unlock time candidate
    function testFuzz_property(address actor, uint256 sendValue, uint256 unlockCandidate) public {
        // Keep actor usable and avoid zero-address weirdness
        vm.assume(actor != address(0));
        // Bound the sendValue to a reasonable range so vm.deal works and avoid overflow accounting
        uint256 value = bound(sendValue, 0, 10 ether);
        // Make unlockCandidate cover wide range including past and future
        uint256 t = unlockCandidate;

        // Fund the actor so it can send value
        vm.deal(actor, value);

        // Actor calls Put with the candidate unlock time and value
        vm.prank(actor);
        c.Put{value: value}(t);

        // Read stored unlockTime for actor from the public mapping getter
        (uint256 storedUnlockTime, uint256 storedBalance) = getHolder(actor);

        // The general rule we assert (one assertion): For the correct reference, after Put,
        // storedUnlockTime equals either t (if t >= block.timestamp) or block.timestamp (if t < block.timestamp).
        // This is equivalent to: storedUnlockTime >= block.timestamp && storedUnlockTime >= t implies storedUnlockTime == (t >= block.timestamp ? t : block.timestamp).
        // Simpler check: storedUnlockTime >= block.timestamp && (t < block.timestamp ? storedUnlockTime == block.timestamp : storedUnlockTime == t).

        if (t < block.timestamp) {
            assertTrue(storedUnlockTime == block.timestamp);
        } else {
            assertTrue(storedUnlockTime == t);
        }
    }

    // Helper to read the public mapping Acc (auto-generated getter has signature Acc(address) returns (uint unlockTime, uint balance))
    function getHolder(address who) internal returns (uint256, uint256) {
        // Call the auto-generated getter via low-level call to ensure compatibility with ABI
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("Acc(address)", who));
        require(ok, "getter call failed");
        (uint256 unlockTime, uint256 balance) = abi.decode(ret, (uint256, uint256));
        return (unlockTime, balance);
    }
}

