pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor will call Put and newUnlock is the _unlockTime argument
    function testFuzz_property(address actor, uint256 newUnlock, uint256 value) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // keep value reasonably bounded to avoid overflow in test env
        value = bound(value, 0, 10 ether);

        // ensure actor has ETH to send
        vm.deal(actor, value);

        // capture prior unlockTime for actor
        uint256 prior = c.Acc(actor).unlockTime;

        // set block timestamp to a reproducible value
        vm.warp(1_000_000);
        uint256 beforeTs = block.timestamp;

        // actor performs Put{value: value}(newUnlock)
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: value}(abi.encodeWithSignature("Put(uint256)", newUnlock));

        // After call, read stored unlockTime
        uint256 after = c.Acc(actor).unlockTime;

        // General rule: reference C never decreases the stored unlockTime below either the prior value or current block.timestamp.
        // Therefore after >= prior && after >= beforeTs
        // This assertion holds for the reference for all inputs; the mutant that assigns _unlockTime directly can fail it when newUnlock < beforeTs and newUnlock < prior.
        assertTrue(after >= prior && after >= beforeTs);
    }
}

